func authoredM2Meaning(spec m2Spec, language string) sem.Meaning {
	subject := sem.Node{ID: "author.subject", Kind: sem.Referent, Concept: core.ID("entity." + spec.subject)}
	if spec.person != "" {
		subject.Person = spec.person
		subject.Number = spec.number
		subject.PronounGender = spec.gender
		if language == "en" && spec.id == "A1-027" {
			subject.PronounGender = ""
		}
	} else {
		subject.Number = "singular"
		if language == "en" {
			subject.Definiteness = "indefinite"
		}
	}
	role := "agent"
	objectRole := "patient"
	if spec.predicate == "have" {
		role = "holder"
		objectRole = "theme"
	}
	if spec.predicate == "help" {
		objectRole = "beneficiary"
	}
	event := sem.Node{ID: "author.event", Kind: sem.Event, Concept: core.ID("predicate." + spec.predicate), Tense: "present", Arguments: []sem.Argument{{Role: role, Target: subject.ID}}}
	nodes := []sem.Node{subject, event} // different order and IDs from the parser
	if spec.object != "" {
		object := sem.Node{ID: "author.object", Kind: sem.Referent, Concept: core.ID("entity." + spec.object)}
		if !spec.mass {
			object.Number = "singular"
		}
		if spec.lexicalPlural && language == "pl" {
			object.Number = ""
		}
		if language == "en" && !spec.mass {
			object.Definiteness = "indefinite"
		}
		event.Arguments = append(event.Arguments, sem.Argument{Role: objectRole, Target: object.ID})
		nodes[1] = event
		nodes = append(nodes, object)
	}
	return sem.Meaning{Root: event.ID, Nodes: nodes}
}

func TestM2IndependentMeaningRequirements(t *testing.T) {
	c, err := core.BaseA1()
	if err != nil {
		t.Fatal(err)
	}
	if len(m2Requirements) != 30 {
		t.Fatalf("want 30 independent event meanings, got %d", len(m2Requirements))
	}
	for i, spec := range m2Requirements {
		if spec.id != cases[20+i].ID {
			t.Fatalf("fixture mismatch %q %q", spec.id, cases[20+i].ID)
		}
		for _, lang := range []string{"pl", "en"} {
			m := authoredM2Meaning(spec, lang)
			if err := sem.Validate(m, c); err != nil {
				t.Errorf("%s %s: %v", spec.id, lang, err)
			}
		}
	}
}
